from falcon import Request, Response, HTTPBadRequest, before
from logging import Logger
from shr import PropertyResponse, MethodResponse, PreProcessRequest, \
                StateValue, get_request_field, to_bool
from exceptions import *        # Nothing but exception classes
from focuserdevice import FocuserDevice
from config import Config
import datetime

logger: Logger = None

# ----------------------
# MULTI-INSTANCE SUPPORT
# ----------------------
# If this is > 0 then it means that multiple devices of this type are supported.
# Each responder on_get() and on_put() is called with a devnum parameter to indicate
# which instance of the device (0-based) is being called by the client. Leave this
# set to 0 for the simple case of controlling only one instance of this device type.
#
maxdev = 0                      # Single instance

# -----------
# DEVICE INFO
# -----------
# Static metadata not subject to configuration changes
class FocuserMetadata:
    """ Metadata describing the Focuser Device. Edit for your device"""
    Name = 'Sample Focuser'
    Version = '0.1'
    Description = 'My ASCOM Focuser'
    DeviceType = 'Focuser'
    DeviceID = '8D469E90-67A0-4823-A9E1-E206A5873D17' # https://guidgenerator.com/online-guid-generator.aspx
    Info = 'Alpaca Sample Device\nImplements IFocuser\nASCOM Initiative'
    MaxDeviceNumber = maxdev
    InterfaceVersion = 4

# --------------------
# SIMULATED FOCUSER ()
# --------------------
focuser_dev = None
# At app init not import :-)
def start_focuser_device(logger: Logger):
    logger = logger
    global focuser_dev
    focuser_dev = FocuserDevice(logger)
    focuser_dev.can_reverse = Config.can_reverse
    focuser_dev.step_size = Config.step_size
    focuser_dev.steps_per_sec = Config.steps_per_sec
    focuser_dev.sync_write_connected = Config.sync_write_connected


