@before(PreProcessRequest(maxdev))
class devicestate:

    def on_get(self, req: Request, resp: Response, devnum: int):
        if not focuser_dev.connected:
            resp.text = PropertyResponse(None, req,
                            NotConnectedException()).json
            return
        try:
            # ----------------------
            val = []
            val.append(StateValue('IsMoving', focuser_dev.is_moving))
            val.append(StateValue('Position', focuser_dev.position))
            val.append(StateValue('Temperature', focuser_dev.temperature))
            val.append(StateValue('TimeStamp', datetime.datetime.utcnow().isoformat()))
            resp.text = PropertyResponse(val, req).json
        except Exception as ex:
            resp.text = PropertyResponse(None, req,
                            DriverException(0x500, 'focuser.Devicestate failed', ex)).json


